{
  "name": "dashboard",
  "version": "0.5.14",
  "description": "Unified workbench: a status band for subagents and mmrun reviews, plus a seven-page pane (Overview / Agents / Reviews / GPU / Timeline / Usage / Progress; Reviews, GPU and Progress show once they have data); the Progress page lists the per-project progress board, recorded after each typed turn that changed files or made a commit",
  "author": {
    "name": "Paradox07127"
  },
  "types": "./types/index.d.ts",
  "userConfig": {
    "gpuHosts": {
      "type": "string",
      "title": "GPU hosts",
      "description": "Comma-separated ssh host names; a Bash call starting with `ssh <host>` opens the workbench on that host's GPU page.",
      "default": ""
    },
    "cacheTtlMinutes": {
      "type": "number",
      "title": "Prompt cache TTL (minutes)",
      "description": "Main thread idle this long: the band warns that the next message rewrites the prompt cache. The TTL read from the transcript, or reported by a model switch, overrides it for the session.",
      "default": 60
    },
    "language": {
      "type": "string",
      "options": [
        "auto",
        "zh-CN",
        "en"
